PAYLOAD_SHA256 = '348897176d04a4a9e9c543377eccc5185cdc07b3c5f0f545da41c7ade1f6691b'
FILES = {'round1/START.py': 'a03cb53e89f19f6a48dc6159e61e322042bba8bf709c4a97a3e6db8bfe7b2987', 'round1/worker.py': 'cdf0dfb2a3e850da0b99ddca8b50560a33bae780bb6f7a12916e75c95cd80836', 'round1/kernel_bridge.py': '929fc69cb5485b83f4a0900b38f49e4b11ab20b3278b0e980cb8b9f5e56fd7bf', 'round1/audited_runtime.py': '8a637c1df0ef9869da7bdfbe94590a120b599dcf9e48dca5d6fdcde82ce82550', 'round1/hardware_comparison.py': '816a935b302bc0f464d1748706e17939dc8db11f681f6e26df20261d08565417', 'round1/scheduler.py': '89a477ccc014f5ce2ce77293dc92dbb1b35d97b829be5e61944f751865326af3', 'round1/handoff.py': '9172cfbe0c775a1867e32553cee207d47009cd3bb1904ce27037a1fdfc8c8663', 'round1/retire_legacy.py': 'ad944f07eb1fdc5a5eeea9000bf0dfa66a198d499e87b6d369287960d2880ce3', 'round1/monitor.py': '8b69be67c776fad10976f3e871e978e9a1510c1e77db4636277da96af366e2ea', 'round1/auto_summary.py': 'aac37015d460541221224d83fa1ca676748233713fd9c48c89fb81581fe63415', 'round1/summary_transport.py': 'b8d808ad45209d06c68fda81fd0a9821f271f19fa18269a85ab27a246654ecf3', 'round56/START.py': '5e735878fb1a0bbada23cf340362a7bd9b94b5c7f7cef1701a4cc8346802fc03', 'round56/coordinator.py': '990e11bb88dd123b69b8845dc7c8d5b7f12cffc32aba34165bb231787ed4e63d', 'round56/three_jobs.py': 'b1620be3b102398c4ec2ebe2e99aa0d84ba06ef8ebf74bbc56fabc54a601247f', 'round56/generic_scheduler.py': 'f4dff12087db07793a8956c92642e5c9a4619699b45b736bb068f52ccf656bb8', 'round56/migrate.py': '43d835ad981f3706c54ef83798764d03070daf756427dc755f6048c0f9e696b2', 'round56/backend_entry.py': 'c57f9b06a8ea12be577e5ada4f994c898ab5d6df9a468f0506822dc3816494f5', 'round56/monitor.py': 'c67925d67037e740246716df1fd98394ef0a3ad017ef36db2327395f5f20cb48', 'round56/auto_summary.py': 'aac37015d460541221224d83fa1ca676748233713fd9c48c89fb81581fe63415', 'round56/summary_transport.py': 'b8d808ad45209d06c68fda81fd0a9821f271f19fa18269a85ab27a246654ecf3', 'repair_manager.py': 'd499e0530e8b5ba7729ead49be8d09cbb77ad5898b8e7ca47d5c06acca2bb29a'}

def valid(directory):
    try:
        for name,expected in FILES.items():
            path=directory/name
            if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:return False
        return True
    except OSError:return False

def install(base):
    base.mkdir(parents=True,exist_ok=True)
    destination=base/PAYLOAD_SHA256[:24]
    with (base/'.install.lock').open('a') as handle:
        fcntl.flock(handle,fcntl.LOCK_EX)
        if valid(destination):return destination
        data=base64.b85decode(PAYLOAD)
        if hashlib.sha256(data).hexdigest()!=PAYLOAD_SHA256:raise ValueError('Embedded payload checksum differs')
        stage=pathlib.Path(tempfile.mkdtemp(prefix='.install-',dir=base))
        try:
            with tarfile.open(fileobj=io.BytesIO(data),mode='r:gz') as archive:
                members=archive.getmembers()
                if {m.name for m in members}!=set(FILES):raise ValueError('Payload file list differs')
                for member in members:
                    if not member.isfile() or member.name not in FILES or '..' in pathlib.PurePosixPath(member.name).parts:
                        raise ValueError('Unexpected installation member')
                    content=archive.extractfile(member).read()
                    if hashlib.sha256(content).hexdigest()!=FILES[member.name]:raise ValueError('Module checksum differs')
                    target=stage/member.name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(content)
            if destination.exists():
                os.rename(destination,base/(destination.name+'.previous-'+str(time.time_ns())))
            os.rename(stage,destination)
            return destination
        finally:
            if stage.exists():shutil.rmtree(stage)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--round',type=int,choices=(1,5,6),dest='round_number')
    parser.add_argument('--repair',action='store_true',help='Adopt existing held jobs after the Slurm NumNodes display fix')
    parser.add_argument('--root',default='/public/home/zhuziyuan/projects/paper3')
    parser.add_argument('--install-base',default=str(pathlib.Path.home()/'paper3-parallel-migrations'))
    parser.add_argument('--old-job')
    parser.add_argument('--credentials')
    parser.add_argument('--direct-package')
    parser.add_argument('--payload-manifest')
    parser.add_argument('--scientific-package')
    parser.add_argument('--execute',action='store_true')
    parser.add_argument('--install-only',action='store_true')
    args=parser.parse_args()
    if not args.repair and args.round_number is None:parser.error('--round or --repair is required')
    package=install(pathlib.Path(args.install_base).expanduser())
    print(json.dumps({'status':'PARALLEL_PACKAGE_VERIFIED','package':str(package),'round':args.round_number,
          'payload_sha256':PAYLOAD_SHA256,'school_jobs_submitted_by_installer':False}),flush=True)
    if args.install_only:return 0
    if args.repair:
        command=[sys.executable,'-I','-S','-B','-u',str(package/'repair_manager.py'),'--root',args.root,'--package',str(package)]
        if args.execute:command+=['--execute']
        return subprocess.run(command).returncode
    folder=package/('round1' if args.round_number==1 else 'round56')
    command=[sys.executable,'-I','-S','-B','-u',str(folder/'START.py'),'--root',args.root,'--python',sys.executable]
    if args.round_number!=1:command+=['--round',str(args.round_number)]
    if args.old_job:command+=['--old-job',args.old_job]
    if args.credentials:command+=['--credentials',args.credentials]
    for name in ('direct_package','payload_manifest','scientific_package'):
        value=getattr(args,name)
        if value:
            if (args.round_number==1)==(name=='scientific_package'):parser.error('Package option does not apply to this round')
            command+=['--'+name.replace('_','-'),value]
    if args.execute:command+=['--execute']
    return subprocess.run(command).returncode

if __name__=='__main__':raise SystemExit(main())
